type Request struct {
    Data  []int
    Reply chan int // the return address travels with the request
}

func worker(reqs <-chan *Request) {
    for req := range reqs {
        req.Reply <- sum(req.Data) // answer straight to the requester
    }
}

answers := make(chan int)
reqs <- &Request{Data: []int{3, 4, 5}, Reply: answers}
fmt.Println(<-answers)

// requester: nc.Request creates the inbox and sets the reply subject
msg, err := nc.Request("fib", []byte("10"), 2*time.Second)

// service: msg.Reply is the return address
nc.Subscribe("fib", func(m *nats.Msg) {
    _ = nc.Publish(m.Reply, []byte(strconv.Itoa(fib(10))))
})

